def factored_binary_tree_count(arr):
    mod=10**9+7;values=set(arr);dp={}
    for root in sorted(arr):
        dp[root]=1+sum(dp[left]*dp[root//left] for left in dp if root%left==0 and root//left in dp)
    return sum(dp.values())%mod

